    assert_eq!(candidate("a1b2c3d4e5f6g7h8i9j10k11", "abcdefghijk11"), False);
    assert_eq!(candidate("a1b2c3d4e5f6g7h8i9j10k11", "abcdefghijk123"), False);
    assert_eq!(candidate("abcdefghij1234567890", "abcdefghij1234567890"), True);
    assert_eq!(candidate("a1b1c1d1e1f1g1h1i1j1k1l1m1n1o1p1q1r1s1t1u1v1w1x1y1z1", "abcdefghijklmnopqrstuvwxyz123"), False);
    assert_eq!(candidate("a10b", "aaaaaaaaaab"), False);
    assert_eq!(candidate("abcdefghij123456789012345678", "abcdefghij123456789012345678"), Execution timed out);
}
